using System; using System.Collections.ObjectModel; using System.Linq; using System.Threading; using System.Threading.Tasks; using System.Windows.Input; using Microsoft.Extensions.Logging; using PhotoBooth.Admin.UI.Mvvm; using PhotoBooth.Admin.UI.Services; using PhotoBooth.Core.Models; using PhotoBooth.Core.Services;
namespace PhotoBooth.Admin.UI.ViewModels { public sealed class FrameManagerViewModel:PageViewModel { readonly IFrameService service;readonly ISettingsService settings;readonly IFileDialogService dialog;readonly ILogger<FrameManagerViewModel> log;string search="";string sort="Pinned first";Frame selected;string message;public FrameManagerViewModel(IFrameService s,ISettingsService st,IFileDialogService d,ILogger<FrameManagerViewModel> l){service=s;settings=st;dialog=d;log=l;ImportCommand=new AsyncCommand(_=>Import());DeleteCommand=new AsyncCommand(_=>Delete(),_=>SelectedFrame!=null);PinCommand=new AsyncCommand(_=>Pin(),_=>SelectedFrame!=null);RefreshCommand=new AsyncCommand(_=>Load());SortOptions=new[]{"Pinned first","Newest","Name"};_=Load();}public override string Title=>"Frame Manager";public ObservableCollection<Frame> Frames{get;}=new ObservableCollection<Frame>();public ObservableCollection<Frame> VisibleFrames{get;}=new ObservableCollection<Frame>();public string[] SortOptions{get;}public string Search{get=>search;set{if(Set(ref search,value))Apply();}}public string Sort{get=>sort;set{if(Set(ref sort,value))Apply();}}public Frame SelectedFrame{get=>selected;set{if(Set(ref selected,value)){System.Windows.Input.CommandManager.InvalidateRequerySuggested();}}}public string Message{get=>message;set=>Set(ref message,value);}public const int MaxPins=10;int pinnedCount;public int PinnedCount{get=>pinnedCount;private set=>Set(ref pinnedCount,value);}public ICommand ImportCommand{get;}public ICommand DeleteCommand{get;}public ICommand PinCommand{get;}public ICommand RefreshCommand{get;}async Task Load(){try{Frames.Clear();foreach(var x in await service.GetAllAsync(CancellationToken.None))Frames.Add(x);PinnedCount=Frames.Count(y=>y.IsPinned);Apply();}catch(Exception e){Fail(e,"Frames could not be loaded");}}void Apply(){var q=Frames.Where(x=>string.IsNullOrWhiteSpace(Search)||(x.Name??"").IndexOf(Search,StringComparison.OrdinalIgnoreCase)>=0);q=Sort=="Name"?q.OrderBy(x=>x.Name):Sort=="Newest"?q.OrderByDescending(x=>x.CreatedAtUtc):q.OrderByDescending(x=>x.IsPinned).ThenByDescending(x=>x.CreatedAtUtc);VisibleFrames.Clear();foreach(var x in q)VisibleFrames.Add(x);}async Task Import(){var path=dialog.PickPng();if(path==null)return;try{var s=await settings.GetAsync(CancellationToken.None)??new Settings();await service.ImportAsync(path,new FrameAnalysisOptions{AlphaThreshold=s.TransparentAlphaThreshold,MinimumArea=s.MinimumSlotArea,MinimumWidth=s.MinimumSlotWidth,MinimumHeight=s.MinimumSlotHeight,IgnoreBorderConnectedRegions=s.IgnoreBorderTransparency,MaximumSlots=8},CancellationToken.None);Message="Frame imported";await Load();}catch(Exception e){Fail(e,e.Message.Contains("Invalid Frame")?"Invalid Frame":"Import failed");}}async Task Delete(){try{await service.DeleteAsync(SelectedFrame.Id,CancellationToken.None);Message="Frame deleted";await Load();}catch(Exception e){Fail(e,"Delete failed");}}async Task Pin(){try{await service.SetPinnedAsync(SelectedFrame.Id,!SelectedFrame.IsPinned,CancellationToken.None);await Load();}catch(Exception e){Fail(e,e.Message);}}void Fail(Exception e,string text){log.LogError(e,text);Message=text;} } }
